args.content:
import { getNotificationPreference, toggleNotifications } from './actions';

export default async function Home() {
  const isEnabled = await getNotificationPreference();

  return (
    <main style={{ padding: '2rem', fontFamily: 'system-ui' }}>
      <h1>Settings</h1>
      <p>
        Notifications are currently: <strong>{isEnabled ? 'ON' : 'OFF'}</strong>
      </p>

      {/* 
        Using a form with a Server Action.
        When submitted, the Server Action will toggle the preference and call refresh(), 
        causing Next.js to update the page to show the new state without a full reload or redirect.
      */}
      <form action={toggleNotifications}>
        <button 
          type="submit" 
          style={{ 
            padding: '0.5rem 1rem', 
            cursor: 'pointer', 
            backgroundColor: '#0070f3', 
            color: 'white', 
            border: 'none', 
            borderRadius: '4px' 
          }}
        >
          Toggle Notifications
        </button>
      </form>
    </main>
  );
}

